window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-41b7367d172de384"]={"versions": [{"id": "FIG-41b7367d172de384", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für VFB-Timing-Events im Kontext der AUTOSAR Adaptive Platform Timing Extensions (<code>AUTOSAR_TPS_AdaptivePlatformTimingExtensions</code>). Es definiert das Blueprint-Konzept für Virtual Function Bus (VFB) Timing-Events (<code>TDEventVfb</code>) und deren Port-spezifische Spezialisierung zur Referenzierung von Blueprint- und Prototyp-Elementen innerhalb von Software-Architekturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Metamodell-Elemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>TimingDescriptionEvent</code></strong> (Stereotyp <code>«TimingDescription»</code>): Abstrakte Basisklasse für Timing-Events.\n</li><li><strong><code>TDEventVfb</code></strong>: Spezialisiert <code>TimingDescriptionEvent</code>. Besitzt eine Kompositionsbeziehung <code>+component</code> mit Kardinalität <code>0..1</code> auf ein Ziel vom Typ <code>ComponentInCompositionInstanceRef</code> (Stereotyp <code>«AtpInstanceRef»</code>).\n</li><li><strong><code>TDEventVfbPort</code></strong>: Spezialisiert <code>TDEventVfb</code>. Enthält das öffentliche Attribut <code>+ isExternal: Boolean</code>.\n<ul class=\"fig-list\"><li>Gerichtete Assoziation <code>+portPrototypeBlueprint</code> mit Kardinalität <code>0..1</code> auf <code>PortPrototypeBlueprint</code> (Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpStructureElement»</code>).\n</li><li>Gerichtete Assoziation <code>+port</code> mit Kardinalität <code>0..1</code> auf <code>PortPrototype</code> (Stereotypen <code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>).\n</li></ul>\n</li><li><strong><code>ComponentInCompositionInstanceRef</code></strong> (hervorgehoben als Instanzreferenz via <code>«AtpInstanceRef»</code>): Referenziert die Komponenteninstanz innerhalb einer Kompositionshierarchie.\n</li><li><strong><code>PortPrototypeBlueprint</code></strong>: Blueprint-Definition eines Port-Prototyps.\n</li><li><strong><code>PortPrototype</code></strong>: Konkreter Port-Prototyp.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Interaktionssequenzen. Zur Laufzeit bzw. während der Modellierung referenziert ein <code>TDEventVfbPort</code> optional entweder eine Blueprint-Spezifikation (<code>PortPrototypeBlueprint</code>) im Entwurfsstadium oder einen konkreten <code>PortPrototype</code> sowie optional über die Elternklasse <code>TDEventVfb</code> eine Komponenteninstanz (<code>ComponentInCompositionInstanceRef</code>), um Kommunikationsereignisse an Software-Ports timing-bezogen zu erfassen. Das Flag <code>isExternal</code> kennzeichnet, ob das Ereignis an einer externen Schnittstelle auftritt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die AUTOSAR Adaptive Platform Timing Extensions. Modellierer und Werkzeughersteller müssen sicherstellen, dass Instanzen von <code>TDEventVfbPort</code> das Attribut <code>isExternal</code> bereitstellen und maximal eine Blueprint- bzw. Port-Referenz sowie optional eine Komponenten-Instanzreferenz (<code>0..1</code>) zuweisen. Die Instanzreferenz <code>ComponentInCompositionInstanceRef</code> folgt dem AUTOSAR-Instanzreferenz-Muster (<code>AtpInstanceRef</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c364e8ac38cbb65b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für VFB-Timing-Events im Kontext der AUTOSAR Adaptive Platform Timing Extensions (<code>AUTOSAR_TPS_AdaptivePlatformTimingExtensions</code>). Es definiert das Blueprint-Konzept für Virtual Function Bus (VFB) Timing-Events (<code>TDEventVfb</code>) und deren Port-spezifische Spezialisierung zur Referenzierung von Blueprint- und Prototyp-Elementen innerhalb von Software-Architekturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Metamodell-Elemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>TimingDescriptionEvent</code></strong> (Stereotyp <code>«TimingDescription»</code>): Abstrakte Basisklasse für Timing-Events.\n</li><li><strong><code>TDEventVfb</code></strong>: Spezialisiert <code>TimingDescriptionEvent</code>. Besitzt eine Kompositionsbeziehung <code>+component</code> mit Kardinalität <code>0..1</code> auf ein Ziel vom Typ <code>ComponentInCompositionInstanceRef</code> (Stereotyp <code>«AtpInstanceRef»</code>).\n</li><li><strong><code>TDEventVfbPort</code></strong>: Spezialisiert <code>TDEventVfb</code>. Enthält das öffentliche Attribut <code>+ isExternal: Boolean</code>.\n<ul class=\"fig-list\"><li>Gerichtete Assoziation <code>+portPrototypeBlueprint</code> mit Kardinalität <code>0..1</code> auf <code>PortPrototypeBlueprint</code> (Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpStructureElement»</code>).\n</li><li>Gerichtete Assoziation <code>+port</code> mit Kardinalität <code>0..1</code> auf <code>PortPrototype</code> (Stereotypen <code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>).\n</li></ul>\n</li><li><strong><code>ComponentInCompositionInstanceRef</code></strong> (hervorgehoben als Instanzreferenz via <code>«AtpInstanceRef»</code>): Referenziert die Komponenteninstanz innerhalb einer Kompositionshierarchie.\n</li><li><strong><code>PortPrototypeBlueprint</code></strong>: Blueprint-Definition eines Port-Prototyps.\n</li><li><strong><code>PortPrototype</code></strong>: Konkreter Port-Prototyp.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Interaktionssequenzen. Zur Laufzeit bzw. während der Modellierung referenziert ein <code>TDEventVfbPort</code> optional entweder eine Blueprint-Spezifikation (<code>PortPrototypeBlueprint</code>) im Entwurfsstadium oder einen konkreten <code>PortPrototype</code> sowie optional über die Elternklasse <code>TDEventVfb</code> eine Komponenteninstanz (<code>ComponentInCompositionInstanceRef</code>), um Kommunikationsereignisse an Software-Ports timing-bezogen zu erfassen. Das Flag <code>isExternal</code> kennzeichnet, ob das Ereignis an einer externen Schnittstelle auftritt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die AUTOSAR Adaptive Platform Timing Extensions. Modellierer und Werkzeughersteller müssen sicherstellen, dass Instanzen von <code>TDEventVfbPort</code> das Attribut <code>isExternal</code> bereitstellen und maximal eine Blueprint- bzw. Port-Referenz sowie optional eine Komponenten-Instanzreferenz (<code>0..1</code>) zuweisen. Die Instanzreferenz <code>ComponentInCompositionInstanceRef</code> folgt dem AUTOSAR-Instanzreferenz-Muster (<code>AtpInstanceRef</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7f4408f2e308c2cc", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für VFB-Timing-Events im Kontext der AUTOSAR Adaptive Platform Timing Extensions (<code>AUTOSAR_TPS_AdaptivePlatformTimingExtensions</code>). Es definiert das Blueprint-Konzept für Virtual Function Bus (VFB) Timing-Events (<code>TDEventVfb</code>) und deren Port-spezifische Spezialisierung zur Referenzierung von Blueprint- und Prototyp-Elementen innerhalb von Software-Architekturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Metamodell-Elemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>TimingDescriptionEvent</code></strong> (Stereotyp <code>«TimingDescription»</code>): Abstrakte Basisklasse für Timing-Events.\n</li><li><strong><code>TDEventVfb</code></strong>: Spezialisiert <code>TimingDescriptionEvent</code>. Besitzt eine Kompositionsbeziehung <code>+component</code> mit Kardinalität <code>0..1</code> auf ein Ziel vom Typ <code>ComponentInCompositionInstanceRef</code> (Stereotyp <code>«AtpInstanceRef»</code>).\n</li><li><strong><code>TDEventVfbPort</code></strong>: Spezialisiert <code>TDEventVfb</code>.\n<ul class=\"fig-list\"><li>Gerichtete Assoziation <code>+portPrototypeBlueprint</code> mit Kardinalität <code>0..1</code> auf <code>PortPrototypeBlueprint</code> (Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpStructureElement»</code>).\n</li><li>Gerichtete Assoziation <code>+port</code> mit Kardinalität <code>0..1</code> auf <code>PortPrototype</code> (Stereotypen <code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>).\n</li></ul>\n</li><li><strong><code>ComponentInCompositionInstanceRef</code></strong> (hervorgehoben als Instanzreferenz via <code>«AtpInstanceRef»</code>): Referenziert die Komponenteninstanz innerhalb einer Kompositionshierarchie.\n</li><li><strong><code>PortPrototypeBlueprint</code></strong>: Blueprint-Definition eines Port-Prototyps.\n</li><li><strong><code>PortPrototype</code></strong>: Konkreter Port-Prototyp.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Interaktionssequenzen. Zur Laufzeit bzw. während der Modellierung referenziert ein <code>TDEventVfbPort</code> optional entweder eine Blueprint-Spezifikation (<code>PortPrototypeBlueprint</code>) im Entwurfsstadium oder einen konkreten <code>PortPrototype</code> sowie optional über die Elternklasse <code>TDEventVfb</code> eine Komponenteninstanz (<code>ComponentInCompositionInstanceRef</code>), um Kommunikationsereignisse an Software-Ports timing-bezogen zu erfassen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die AUTOSAR Adaptive Platform Timing Extensions. Modellierer und Werkzeughersteller müssen sicherstellen, dass Instanzen von <code>TDEventVfbPort</code> maximal eine Blueprint- bzw. Port-Referenz (<code>0..1</code>) sowie optional eine Komponenten-Instanzreferenz (<code>0..1</code>) zuweisen. Die Instanzreferenz <code>ComponentInCompositionInstanceRef</code> folgt dem AUTOSAR-Instanzreferenz-Muster (<code>AtpInstanceRef</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-41b7367d172de384", "to": "FIG-c364e8ac38cbb65b", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c364e8ac38cbb65b", "to": "FIG-7f4408f2e308c2cc", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>+ isExternal: Boolean</code> in der Klasse <code>TDEventVfbPort</code> entfernt.\n</li></ul>"}]};
